// QA-02 (image-enrichment B2): structural + regression coverage. These tests guard
// the cross-cutting STRUCTURAL ACs that no per-module unit test can assert alone:
// the additivity invariant (AC-3/AC-queue — B2 touched none of proto/api/enrich/sdk;
// B1 queue source byte-identical) and the TV no-cover-art regression (AC-image/R-I4
// — module-type-gated discovery must NOT leak image cover-art into TV scans, and
// must NOT leak video into image scans). Plus the pure-Go build (AC-2: the 3 plugin
// packages + server build CGO_ENABLED=0, proving no cgo crept in — a behavioral
// proof, stronger than a grep for `import "C"`).
//
// Redundancy note (code-quality gate #6): the module-registry compose + idempotent
// seed are DROPPED here — already proven by internal/module/registry_test.go
// (TestOpen_ImageSeeded, TestOpen_IdempotentSeedImage). The TV cover-art direction
// (.jpg/.png absent from a TV lib) is GENUINELY NEW — the coder golden + QA-01
// cover only the image-lib-gates-out-.mkv direction; this file covers the reverse.
//
// Tests skip cleanly under -short / missing ffmpeg (the TV regression needs a real
// .mkv). The additive/pure-Go probes run regardless (no exiftool/ffmpeg needed).
package mellifera_test

import (
	"net/http"
	"os"
	"os/exec"
	"path/filepath"
	"strings"
	"testing"
	"time"
)

// b2MergeBase is the feature's merge base (main @ e2a7562 — confirmed
// merge-base(HEAD, main)). All additive diff probes anchor here. HEAD == e2a7562
// during development (B2 work is uncommitted in the working tree), so the diff is
// the working-tree diff; after commit it is the branch diff. Either way, empty in
// the no_seam trees = additive holds.
const b2MergeBase = "e2a7562"

// b2Token is the admin bearer for the TV regression server.
const b2Token = "qa-b2-regression-token"

// TestB2_Ac3Additive is the AC-3/AC-queue regression guard: B2 touched NONE of the
// shipped proto/api/enrich/sdk contract trees, and the B1 queue source
// (internal/enrich) is byte-identical. This is the user's hardest constraint
// ("image support is purely additive"). Pinned as a Go test so it runs on every
// `go test ./...` (the pipeline-local bash gate does not survive into CI). Anchored
// at b2MergeBase; asserts the no_seam trees have ZERO changed paths.
func TestB2_Ac3Additive(t *testing.T) {
	if testing.Short() {
		t.Skip("additive probe: skips under -short (shells git)")
	}
	root := moduleRoot(t)

	// AC-3: B2's additivity — proto/enrich/sdk untouched (B2's plugin/queue/sdk contract).
	// internal/api is no longer guarded here: later features (web-ui) legitimately extend
	// the api source (roles, endpoints); web-ui's own AC-7 probe guards forward additivity.
	noSeam := []string{"proto/", "internal/enrich/", "pkg/sdk/"}
	out := b2Git(t, root, append([]string{"diff", "--name-only", b2MergeBase, "--"}, noSeam...)...)
	if changed := strings.TrimSpace(string(out)); changed != "" {
		t.Errorf("AC-3/AC-queue ADDITIVITY BREACH: B2 modified no_seam trees (must be additive only):\n%s", changed)
	}

	// AC-queue: B1 queue source (internal/enrich) untouched — assert on the stat
	// (byte-identical: zero insertions/deletions).
	statOut := b2Git(t, root, "diff", "--stat", b2MergeBase, "--", "internal/enrich/")
	if changed := strings.TrimSpace(string(statOut)); changed != "" {
		t.Errorf("AC-queue B1 QUEUE MODIFIED: internal/enrich must be byte-identical:\n%s", changed)
	}

	// AC-2 (no-dep) RETIRED for go.mod/go.sum: web-ui Phase 1 legitimately adds the
	// first Go dependency (swaggo/http-swagger for Swagger UI), so this guard no
	// longer holds repo-wide. B2's no-new-dep invariant was true at B2's merge;
	// forward additivity (proto/sdk/scan/enrich) is guarded by each feature's AC-7.
}

// b2Git runs git with the given args from dir, failing the test on a non-zero git
// exit (a git error here is a real test failure, not an additive-clean signal).
func b2Git(t *testing.T, dir string, args ...string) []byte {
	t.Helper()
	cmd := exec.Command("git", args...)
	cmd.Dir = dir
	out, err := cmd.Output()
	if err != nil {
		t.Fatalf("git %s (in %s): %v: %s", strings.Join(args, " "), dir, err, out)
	}
	return out
}

// TestB2_PluginsBuildPureGo is the AC-2 build proof: the 3 plugin packages + the
// server build cleanly under CGO_ENABLED=0. A successful CGO_ENABLED=0 build is a
// BEHAVIORAL proof no `import "C"` crept in (cgo fails to build with CGO_ENABLED=0
// when actually used) — stronger and less redundant than a source grep. Each plugin
// is built into a per-test temp dir (hermetic + parallel-safe; `make build-plugin`
// writes to the shared gitignored bin/, which parallel tests would clobber). The
// Makefile TARGET wiring (S7) is verified by the pipeline's bash gate; this test
// verifies the AC-2 pure-Go-build property per-package.
func TestB2_PluginsBuildPureGo(t *testing.T) {
	if testing.Short() {
		t.Skip("pure-Go build probe: skips under -short (compiles binaries)")
	}
	root := moduleRoot(t)
	tmp := t.TempDir()
	// The 3 plugin binaries + the server. CGO_ENABLED=0 is the no-cgo invariant.
	targets := []struct{ bin, pkg string }{
		{"b2-base-scanner", "./plugins/base-scanner"},
		{"b2-tv-parser", "./plugins/tv-parser"},
		{"b2-image-enricher", "./plugins/image-enricher"},
		{"b2-server", "./cmd/mellifera"},
	}
	for _, tg := range targets {
		out := filepath.Join(tmp, tg.bin)
		build := exec.Command("go", "build", "-o", out, tg.pkg)
		build.Dir = root
		build.Env = append(os.Environ(), "CGO_ENABLED=0")
		if b, err := build.CombinedOutput(); err != nil {
			t.Fatalf("AC-2 CGO_ENABLED=0 build %s (%s) failed (cgo or build break): %v: %s", tg.bin, tg.pkg, err, b)
		}
	}
}

// TestB2_TVNoCoverArtRegression is the AC-image/R-I4 regression in the TV
// direction: a TV library containing a real show.mkv PLUS image cover-art
// (cover.jpg, poster.png) discovers ONLY the video — the image files are gated OUT
// (module-type-gated discovery is NOT a union filter). The coder golden + QA-01
// cover only the image-lib-gates-out-.mkv direction; this covers the reverse (the
// direction that protects the shipped TV pipeline from image junk). It also polls
// the show to ready, proving the TV enrichment chain (base-scanner -> tv-parser)
// still drains byte-identically (no B1 regression). REAL subprocesses + real ffmpeg
// .mkv; skips under -short / missing ffmpeg.
func TestB2_TVNoCoverArtRegression(t *testing.T) {
	if testing.Short() {
		t.Skip("TV regression: skips under -short (builds binaries + subprocess)")
	}
	if _, err := exec.LookPath("ffmpeg"); err != nil {
		t.Skip("ffmpeg not on PATH — cannot generate the real .mkv TV fixture")
	}
	if _, err := exec.LookPath("ffprobe"); err != nil {
		t.Skip("ffprobe not on PATH — skipping TV regression (INV-skip-clean)")
	}

	tmp := t.TempDir()
	serverBin := buildBinary(t, tmp, "b2-tv-server", "./cmd/mellifera")
	scannerBin := buildBinary(t, tmp, "b2-tv-scanner", "./plugins/base-scanner")
	tvParserBin := buildBinary(t, tmp, "b2-tv-tvparser", "./plugins/tv-parser")
	imageEnricherBin := buildBinary(t, tmp, "b2-tv-enricher", "./plugins/image-enricher")

	root := t.TempDir()
	const show = "Series.Name.S01E01.1080p.mkv"
	makeMedia(t, filepath.Join(root, show))
	mustWrite(t, filepath.Join(root, "cover.jpg"), []byte("\xff\xd8\xff\xe0FAKEJPEG"))
	mustWrite(t, filepath.Join(root, "poster.png"), []byte("\x89PNG\r\n\x1a\nFAKEPNG"))

	baseURL := startServer(t, serverBin, scannerBin, tvParserBin, imageEnricherBin, tmp, b2Token)
	client := &http.Client{Timeout: httpTimeout}
	libID := createLibrary(t, client, baseURL, b2Token, root) // module_id="tv"

	res := scanLibrary(t, client, baseURL, b2Token, libID)
	// R-I4: ONLY the video is discovered. cover.jpg + poster.png are gated OUT.
	if res.Discovered != 1 || res.Persisted != 1 {
		byRel := indexByPath(t, listItems(t, client, baseURL, b2Token, libID))
		t.Fatalf("R-I4: TV scan discovered=%d persisted=%d, want 1 (only %s; cover.jpg/poster.png must be gated out). items: %v",
			res.Discovered, res.Persisted, show, pathsOf(byRel))
	}
	byRel := indexByPath(t, listItems(t, client, baseURL, b2Token, libID))
	if _, leak := byRel["cover.jpg"]; leak {
		t.Errorf("R-I4: cover.jpg was discovered by the TV module (module-type gating leaked image cover-art)")
	}
	if _, leak := byRel["poster.png"]; leak {
		t.Errorf("R-I4: poster.png was discovered by the TV module (module-type gating leaked image cover-art)")
	}
	if _, ok := byRel[show]; !ok {
		t.Fatalf("R-I4: %s not discovered (TV video fallback must still work); have %v", show, pathsOf(byRel))
	}

	// Regression: the TV item still drains enriched -> ready (B1 queue byte-identical
	// for TV). Bounded poll.
	deadline := time.Now().Add(15 * time.Second)
	for time.Now().Before(deadline) {
		byRel = indexByPath(t, listItems(t, client, baseURL, b2Token, libID))
		if it, ok := byRel[show]; ok && it.Status == "ready" {
			break
		}
		time.Sleep(probeInterval)
	}
	it, _ := indexByPath(t, listItems(t, client, baseURL, b2Token, libID))[show]
	if it.Status != "ready" {
		t.Fatalf("R-I4: %s did not drain to ready (TV pipeline regression); status=%q", show, it.Status)
	}
	// The TV item carries tv-parser provenance (the shipped enricher still binds) —
	// proves image-enricher's addition did not displace tv-parser.
	if _, ok := parseAsyncDoc(t, it.Document).Sources["tv-parser"]; !ok {
		t.Errorf("R-I4: %s sources.tv-parser missing (image module seed must not alter the tv row)", show)
	}
}
